def apply_app_icon(root):
    """Apply the embedded icon to a Tk root window."""
    import tkinter as tk
    image = tk.PhotoImage(data=APP_ICON_DATA)
    root.tk.call("wm", "iconphoto", root._w, image)
    # Retain a Python reference for Tk.
    root._asyura_icon_image = image
    return image
